class Solution {
public:
    vector<vector<int>> flipAndInvertImage(vector<vector<int>>& image) {
        int n = image.size();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n / 2; j++) {
                int temp = image[i][j];
                image[i][j] = 1 - image[i][n - 1 - j];
                image[i][n - 1 - j] = 1 - temp;
            }
            if (n % 2 == 1) {
                image[i][n / 2] = 1 - image[i][n / 2];
            }
        }
        return image;
    }
};
